-- Germany and the USA: country rules, universities, programmes and verified
-- deadlines (official pages, checked 2026-11-20). Fees are in each programme's
-- own currency (fee_currency).
ALTER TABLE programs ADD COLUMN fee_currency TEXT NOT NULL DEFAULT 'EUR';

INSERT INTO countries (code, name, source_url, rules) VALUES ('DE', 'Germany', 'https://www.daad.de', '{"documents": [{"type": "passport", "title": "Passport", "degrees": ["bachelor", "master"], "description": "Valid international passport, photo page scan. Must be valid for the whole visa period."}, {"type": "photo", "title": "Passport photo", "degrees": ["bachelor", "master"], "description": "Recent biometric passport photo."}, {"type": "school_diploma", "title": "School leaving certificate (attestat)", "degrees": ["bachelor"], "description": "Certified copy of your final secondary school certificate."}, {"type": "school_transcript", "title": "School transcript", "degrees": ["bachelor"], "description": "Grades for the final years of school, certified copy."}, {"type": "studienkolleg_or_university", "title": "Studienkolleg result or university transcript", "degrees": ["bachelor"], "description": "Most Uzbek school certificates don''t give direct entry to a German bachelor''s. You need a Studienkolleg (foundation year) and its Feststellungsprüfung, or completed university study in a related subject. Check your case in the DAAD admission database."}, {"type": "bachelor_diploma", "title": "Bachelor''s diploma", "degrees": ["master"], "description": "Certified copy of your bachelor''s degree certificate (or current transcript if you''re in your final year)."}, {"type": "bachelor_transcript", "title": "Bachelor''s transcript", "degrees": ["master"], "description": "Full list of courses, grades and credits, certified copy."}, {"type": "english_certificate", "title": "English certificate (IELTS/TOEFL)", "degrees": ["bachelor", "master"], "condition": "english_taught", "description": "Required for English-taught programmes. Check the programme''s minimum score."}, {"type": "german_certificate", "title": "German certificate (TestDaF, DSH or Goethe C1)", "degrees": ["bachelor", "master"], "condition": "german_taught", "description": "German-taught programmes usually ask for C1: TestDaF, DSH-2 or Goethe-Zertifikat C1."}, {"type": "cv", "title": "CV (tabular)", "degrees": ["master"], "description": "Education, experience and skills in a table, signed and dated."}, {"type": "motivation_letter", "title": "Motivation letter", "degrees": ["bachelor", "master"], "description": "Written by you. The AI coach gives feedback but does not write it."}, {"type": "official_translations", "title": "Certified translations", "degrees": ["bachelor", "master"], "condition": "documents_not_in_english", "description": "Certified translations into German or English of every document issued in Uzbek or Russian."}], "steps": [{"key": "apply", "title": "Apply on the university portal or through uni-assist (EUR 75 for the first programme, EUR 30 for each additional one per semester)"}, {"key": "admission", "title": "Receive the admission letter (Zulassungsbescheid)"}, {"key": "blocked_account", "title": "Open a blocked account (Sperrkonto) with the amount the German government sets for the visa"}, {"key": "visa", "title": "National (D) student visa appointment at the German Embassy in Tashkent"}, {"key": "enrol", "title": "Health insurance and enrolment at the university"}]}');
INSERT INTO countries (code, name, source_url, rules) VALUES ('US', 'United States', 'https://educationusa.state.gov', '{"documents": [{"type": "passport", "title": "Passport", "degrees": ["bachelor", "master"], "description": "Valid international passport, photo page scan."}, {"type": "school_transcript", "title": "High school transcript", "degrees": ["bachelor"], "description": "Grades for your last years of school, with a certified English translation."}, {"type": "school_diploma", "title": "High school diploma (attestat)", "degrees": ["bachelor"], "description": "Your completed secondary school certificate, or proof you will finish before the term starts."}, {"type": "bachelor_diploma", "title": "Bachelor''s diploma", "degrees": ["master"], "description": "Your bachelor''s degree certificate (or current transcript if you''re in your final year)."}, {"type": "bachelor_transcript", "title": "Bachelor''s transcript", "degrees": ["master"], "description": "Transcripts from every university you studied at."}, {"type": "english_certificate", "title": "English test (TOEFL, IELTS or Duolingo)", "degrees": ["bachelor", "master"], "description": "Official scores sent by the testing agency. Each university sets its own minimum."}, {"type": "sat_act", "title": "SAT or ACT scores (if required)", "degrees": ["bachelor"], "description": "Many universities are test-optional; strong scores can still help, especially for competitive majors."}, {"type": "essay", "title": "Personal essay", "degrees": ["bachelor"], "description": "The Common App personal essay plus any university-specific essays. Written by you; the AI coach gives feedback."}, {"type": "statement_of_purpose", "title": "Statement of purpose", "degrees": ["master"], "description": "Your goals, background and reasons for the programme. Written by you."}, {"type": "recommendation_letters", "title": "Recommendation letters", "degrees": ["bachelor", "master"], "description": "Bachelor''s: usually a school counselor and one or two teachers. Master''s: usually three, from professors or employers."}, {"type": "cv", "title": "Résumé / CV", "degrees": ["master"], "description": "Education, experience, projects and skills."}, {"type": "financial_documents", "title": "Proof of funds (bank statement)", "degrees": ["bachelor", "master"], "description": "Bank statement or sponsor letter showing you can pay the first year. The university needs it to issue your Form I-20."}, {"type": "official_translations", "title": "Certified English translations", "degrees": ["bachelor", "master"], "condition": "documents_not_in_english", "description": "Certified English translations of every document issued in Uzbek or Russian."}], "steps": [{"key": "apply", "title": "Apply through the Common App or the university''s own portal"}, {"key": "admission", "title": "Admission decision"}, {"key": "i20", "title": "Send proof of funds; the university issues your Form I-20"}, {"key": "sevis", "title": "Pay the SEVIS I-901 fee"}, {"key": "visa", "title": "F-1 visa interview at the U.S. Embassy in Tashkent"}]}');

