INSERT INTO programs (id, university_id, name, degree, language, requirements, fee_currency, application_fee_eur, fee_note, fee_source_url, call_note, call_source_url, source_url, verified_at)
SELECT (lower(hex(randomblob(4))) || '-' || lower(hex(randomblob(2))) || '-4' || substr(lower(hex(randomblob(2))), 2) || '-' || substr('89ab', 1 + (abs(random()) % 4), 1) || substr(lower(hex(randomblob(2))), 2) || '-' || lower(hex(randomblob(6)))), u.id, 'Computer Science', 'master', 'en', '{"field": "computer_science", "background_fields": ["computer_science", "electrical_engineering"], "adjacent_fields": ["mathematics", "physics", "statistics_data", "engineering_other"], "entry_test": "GRE General Test: RWTH requires the result with your application, before the deadline.", "entry_test_source": "https://sc.informatik.rwth-aachen.de/en/studium/master/informatik/start-ins-studium/", "extra_documents": [{"type": "gre", "title": "GRE General Test result", "description": "Required by RWTH for this programme; it can''t be sent after the deadline."}]}', 'EUR', NULL, NULL, NULL, NULL, 'https://sc.informatik.rwth-aachen.de/en/studium/master/informatik/start-ins-studium/', 'https://sc.informatik.rwth-aachen.de/en/studium/master/informatik/start-ins-studium/', '2026-11-20'
FROM universities u WHERE u.name = 'RWTH Aachen University';

