INSERT INTO program_deadlines (program_id, academic_year, round, opens_on, closes_on, kind, fee_eur, source_url, verified_at, note)
SELECT p.id, '2027/28', 'Winter semester (non-EU applicants)', NULL, '2027-03-01', 'official', NULL, 'https://sc.informatik.rwth-aachen.de/en/studium/master/informatik/start-ins-studium/', '2026-11-20', 'RWTH lists 1 March as the winter-semester deadline for applicants from outside the EU.'
FROM programs p JOIN universities u ON u.id = p.university_id WHERE u.name = 'RWTH Aachen University' AND p.name = 'Computer Science';

